from __future__ import annotations

from datetime import date, datetime
from pathlib import Path

import click
from rich.console import Console
from rich.table import Table
from rich.text import Text

from todo_cli.db import Priority, Todo, add_todo, delete_todo, get_connection, list_todos, mark_done, update_todo

console = Console()

PRIORITY_COLORS = {
    Priority.HIGH: "red",
    Priority.MEDIUM: "yellow",
    Priority.LOW: "green",
}


def _parse_date(value: str) -> date:
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%m/%d"):
        try:
            parsed = datetime.strptime(value, fmt)
            if fmt == "%m/%d":
                parsed = parsed.replace(year=date.today().year)
            return parsed.date()
        except ValueError:
            continue
    raise click.BadParameter(f"Cannot parse date: {value!r}. Use YYYY-MM-DD format.")


class DateType(click.ParamType):
    name = "date"

    def convert(self, value, param, ctx):
        if isinstance(value, date):
            return value
        try:
            return _parse_date(value)
        except click.BadParameter:
            self.fail(f"Cannot parse date: {value!r}. Use YYYY-MM-DD format.", param, ctx)


DATE = DateType()


@click.group()
@click.option("--db", type=click.Path(path_type=Path), default=None, envvar="TODO_DB_PATH", help="Path to SQLite database.")
@click.pass_context
def cli(ctx: click.Context, db: Path | None) -> None:
    """A simple command-line todo list manager."""
    ctx.ensure_object(dict)
    ctx.obj["db_path"] = db


def _get_conn(ctx: click.Context):
    db_path = ctx.obj.get("db_path")
    if db_path:
        return get_connection(db_path)
    return get_connection()


@cli.command()
@click.argument("title")
@click.option("-p", "--priority", type=click.Choice(["high", "medium", "low"], case_sensitive=False), default="medium", help="Task priority.")
@click.option("-d", "--due", type=DATE, default=None, help="Due date (YYYY-MM-DD).")
@click.pass_context
def add(ctx: click.Context, title: str, priority: str, due: date | None) -> None:
    """Add a new todo item."""
    conn = _get_conn(ctx)
    todo = add_todo(conn, title, Priority(priority.lower()), due)
    conn.close()
    console.print(f"Added todo [bold]#{todo.id}[/bold]: {todo.title}")


def _render_todo_table(todos: list[Todo]) -> Table:
    table = Table(show_header=True, header_style="bold")
    table.add_column("ID", style="dim", width=4)
    table.add_column("Title")
    table.add_column("Priority", width=8)
    table.add_column("Due", width=12)
    table.add_column("Status", width=8)

    today = date.today()

    for todo in todos:
        priority_text = Text(todo.priority.value, style=PRIORITY_COLORS[todo.priority])

        if todo.due_date:
            due_text = Text(todo.due_date.isoformat())
            if not todo.done and todo.due_date < today:
                due_text.stylize("bold red")
            elif not todo.done and todo.due_date == today:
                due_text.stylize("bold yellow")
        else:
            due_text = Text("-", style="dim")

        status = Text("done", style="green") if todo.done else Text("pending", style="dim")

        title_style = "strike dim" if todo.done else ""
        title_text = Text(todo.title, style=title_style)

        table.add_row(str(todo.id), title_text, priority_text, due_text, status)

    return table


@cli.command("list")
@click.option("-a", "--all", "show_all", is_flag=True, help="Show completed todos too.")
@click.option("-p", "--priority", type=click.Choice(["high", "medium", "low"], case_sensitive=False), default=None, help="Filter by priority.")
@click.option("--overdue", "due_filter", flag_value="overdue", help="Show only overdue todos.")
@click.option("--today", "due_filter", flag_value="today", help="Show only todos due today.")
@click.option("--week", "due_filter", flag_value="week", help="Show todos due within 7 days.")
@click.pass_context
def list_cmd(ctx: click.Context, show_all: bool, priority: str | None, due_filter: str | None) -> None:
    """List todo items."""
    conn = _get_conn(ctx)
    pri = Priority(priority.lower()) if priority else None
    todos = list_todos(conn, show_done=show_all, priority=pri, due=due_filter)
    conn.close()

    if not todos:
        console.print("No todos found.", style="dim")
        return

    table = _render_todo_table(todos)
    console.print(table)


@cli.command()
@click.argument("todo_id", type=int)
@click.option("-t", "--title", default=None, help="New title.")
@click.option("-p", "--priority", type=click.Choice(["high", "medium", "low"], case_sensitive=False), default=None, help="New priority.")
@click.option("-d", "--due", type=DATE, default=None, help="New due date (YYYY-MM-DD).")
@click.option("--clear-due", is_flag=True, help="Remove the due date.")
@click.pass_context
def edit(ctx: click.Context, todo_id: int, title: str | None, priority: str | None, due: date | None, clear_due: bool) -> None:
    """Edit an existing todo item."""
    if not any([title, priority, due, clear_due]):
        console.print("[red]Nothing to update. Use --title, --priority, --due, or --clear-due.[/red]")
        raise SystemExit(1)
    conn = _get_conn(ctx)
    from todo_cli.db import _UNSET
    pri = Priority(priority.lower()) if priority else None
    due_val = None if clear_due else (due if due else _UNSET)
    todo = update_todo(conn, todo_id, title=title, priority=pri, due_date=due_val)
    conn.close()
    if todo is None:
        console.print(f"[red]Todo #{todo_id} not found.[/red]")
        raise SystemExit(1)
    console.print(f"Updated todo [bold]#{todo.id}[/bold]: {todo.title}")


@cli.command()
@click.argument("todo_id", type=int)
@click.pass_context
def done(ctx: click.Context, todo_id: int) -> None:
    """Mark a todo as done."""
    conn = _get_conn(ctx)
    todo = mark_done(conn, todo_id)
    conn.close()

    if todo is None:
        console.print(f"[red]Todo #{todo_id} not found.[/red]")
        raise SystemExit(1)

    console.print(f"Completed todo [bold]#{todo.id}[/bold]: [strike]{todo.title}[/strike]")


@cli.command()
@click.argument("todo_id", type=int)
@click.pass_context
def delete(ctx: click.Context, todo_id: int) -> None:
    """Delete a todo item."""
    conn = _get_conn(ctx)
    deleted = delete_todo(conn, todo_id)
    conn.close()

    if not deleted:
        console.print(f"[red]Todo #{todo_id} not found.[/red]")
        raise SystemExit(1)

    console.print(f"Deleted todo [bold]#{todo_id}[/bold]")


if __name__ == "__main__":
    cli()

